import sailpoint.dataextract.model.builders.*;
import sailpoint.dataextract.model.configuration.*;
import sailpoint.object.Bundle;
import sailpoint.tools.JsonHelper;


String BUNDLE_NAME = "Biz Role C";
String TRANS_CFG_NAME = "AccessHistoryTransformConfig";

ConfigurationUtil cUtil = new ConfigurationUtil();
TransformationConfig tCfg = cUtil.buildTransformationConfig (context, TRANS_CFG_NAME);
Bundle bundle = context.getObjectByName(Bundle.class, BUNDLE_NAME);

ImageValueObjectBuilder builder = new ImageValueObjectBuilder().setObject(bundle).setTransformationConfig(tCfg).setObjectType("role");
return JsonHelper.toJsonNoEscapes(builder.build(context), JsonHelper.PRETTY_NONULLS);
